        const rows = Array.isArray(response?.designCodes)
          ? response.designCodes
          : [];

        setDesignOptions(
          rows
            .filter((row) => row?.active !== false && row?.designCode)
            .map((row) => ({
              value: String(row.designCode),
              label: row.description
                ? `${row.designCode} — ${row.description}`
                : String(row.designCode),
            })),
        );
      } catch (error) {
        console.error(`[${line}] design-code search failed`, error);
        setDesignOptions([]);
      } finally {
        setDesignSearching(false);
