                <Select
                  showSearch
                  optionFilterProp="label"
                  options={downtimeCodes.options}
                  loading={downtimeCodes.loading}
                  disabled={downtimeCodes.loading || Boolean(downtimeCodes.error)}
                  placeholder="Select a registered downtime code"
                  notFoundContent={downtimeCodes.loading ? "Loading..." : "No downtime codes assigned for this line and category"}
                />
              </Form.Item>
              <Form.Item
                label="Machine"
                name="machine"
                rules={[
                  {
                    required: true,
                    message:
                      "Please select a machine from the registered machine list",
                  },
                ]}
              >
                <AutoComplete
                  options={machineOptions}
                  onSearch={searchMachines}
                  onFocus={() =>
                    searchMachines(downtimeForm.getFieldValue("machine") || "")
                  }
                  placeholder="Type machine name or code"
                  allowClear
                  filterOption={false}
                  notFoundContent={
                    machineSearching ? "Searching..." : "No matching machine"
                  }
                />
              </Form.Item>
              <Form.Item
                label="Downtime Reason"
                name="reason"
                rules={[
                  {
                    required: true,
                    whitespace: true,
                    message: "Please enter the downtime reason",
                  },
                ]}
              >
                <Input.TextArea rows={4} maxLength={500} showCount />
              </Form.Item>
            </Form>
          </>
        ) : null}
      </Modal>
    </div>
  );
}
